#!/usr/bin/env python3
"""docs/ の規約から .claude/rules/*.md を作る。

同じ規約を 2 か所に手で書くと必ずずれる（CLAUDE.md と AGENTS.md がそうだった）。
本文は docs/ に 1 つだけ置き、Claude Code 用の path 付きルールはここから作る。
Codex など rules を読まないエージェントは docs/ を直接読む。

  python3 bin/gen-rules.py           # 生成する
  python3 bin/gen-rules.py --check   # ずれていないか検査する（書かない）

標準ライブラリだけで動く（Windows / macOS / Linux 共通）。
"""

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent

BANNER = (
    "<!-- generated by bin/gen-rules.py from {src} — "
    "編集しないで。本文は {src} を直して make rules -->"
)

# 生成するルール: 出力名 -> (元の doc, 効かせたいファイルの glob)
RULES = {
    "drawing.md": (
        "docs/drawing-floor.md",
        [
            "**/View*.flix",
            "**/src/render/*.flix",
            "**/src/hand/*.flix",
            "**/*Hand.flix",
            "**/*.sprite.json",
            "**/*.theme.json",
            "**/*.palette.json",
            "**/*.fx.json",
            "**/*.shader.json",
        ],
    ),
    "flix.md": (
        "docs/flix-conventions.md",
        ["**/*.flix"],
    ),
}


def render(src_rel, globs):
    body = (ROOT / src_rel).read_text(encoding="utf-8")
    head = ["---", "paths:"]
    head += ['  - "{}"'.format(g) for g in globs]
    head += ["---", "", BANNER.format(src=src_rel), ""]
    return "\n".join(head) + body


# 配り先。agents-pack/rules は make sync-agents が生成ゲームへ配る元になる
# （生成ゲームには docs/ が無いので、生成物の方を持たせる）。
OUT_DIRS = (".claude/rules", "agents-pack/rules")


def main(argv):
    check = "--check" in argv

    stale = []
    for out_rel in OUT_DIRS:
        out_dir = ROOT / out_rel
        if not check:
            out_dir.mkdir(parents=True, exist_ok=True)
        for name, (src_rel, globs) in RULES.items():
            src = ROOT / src_rel
            if not src.is_file():
                print("元の doc がありません: {}".format(src_rel), file=sys.stderr)
                return 1
            want = render(src_rel, globs)
            dest = out_dir / name
            have = dest.read_text(encoding="utf-8") if dest.is_file() else None
            if have == want:
                continue
            if check:
                stale.append("{}/{} が {} とずれています".format(out_rel, name, src_rel))
            else:
                dest.write_text(want, encoding="utf-8")
                print("wrote {}/{} <- {}".format(out_rel, name, src_rel))

    if stale:
        for line in stale:
            print(line, file=sys.stderr)
        print("`make rules` で作り直してください。", file=sys.stderr)
        return 1
    if check:
        print("[gen-rules] OK: .claude/rules と agents-pack/rules は docs/ と一致しています")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
